latest.script:
// 站点数据在 SSR 注入的 __NEXT_DATA__ JSON 里：props.pageProps。
// 首页把内容拆成 bannerList / seoColumnVos[].bookInfos 几块，逐个收集并按 bookId 去重。
function hgProps(raw){
  if (typeof raw !== 'string') return null;
  var i = raw.indexOf('__NEXT_DATA__');
  if (i < 0) return null;
  var s = raw.indexOf('>', i);
  if (s < 0) return null;
  var e = raw.indexOf('</script>', s);
  if (e < 0) return null;
  try {
    var data = JSON.parse(raw.slice(s + 1, e));
    return (data && data.props && data.props.pageProps) || null;
  } catch (err) { return null; }
}
function hgBase(ctx){
  var b = (ctx && ctx.baseUrl) || '';
  return b.charAt(b.length - 1) === '/' ? b.slice(0, -1) : b;
}
function hgItem(book, base){
  if (!book || !book.bookId) return null;
  var cover = book.coverWap || book.wapUrl || book.pcUrl || '';
  if (cover.indexOf('//') === 0) cover = 'https:' + cover;
  var total = parseInt(book.totalChapterNum, 10);
  return {
    id: String(book.bookId),
    title: book.bookName || '',
    cover: cover,
    description: book.introduction || '',
    episodeCount: isNaN(total) ? 0 : total,
    status: book.statusDesc || ''
  };
}
function hgCollect(list, base, out, seen){
  if (!list) return;
  for (var i = 0; i < list.length; i++) {
    var it = hgItem(list[i], base);
    if (!it || seen[it.id]) continue;
    seen[it.id] = 1;
    out.push(it);
  }
}
function parseList(raw, context){
  var props = hgProps(raw);
  if (!props) return [];
  var base = hgBase(context), out = [], seen = {};
  hgCollect(props.bannerList, base, out, seen);
  hgCollect(props.bookList, base, out, seen);
  hgCollect(props.recommendList, base, out, seen);
  var cols = props.seoColumnVos || [];
  for (var i = 0; i < cols.length; i++) hgCollect(cols[i].bookInfos, base, out, seen);
  return out;
}

