episodes.script:
// 详情页的 props.pageProps.chapterList 已包含整本分集，且每集 chapterVideoVo 带播放地址。
// 地址带时效签名，不能直接存进分集（过一段时间再点就 403），
// 因此分集 url 存「详情页地址 + #ep=集ID」，播放时重新取详情页现取地址。
function hgProps(raw){
  if (typeof raw !== 'string') return null;
  var i = raw.indexOf('__NEXT_DATA__');
  if (i < 0) return null;
  var s = raw.indexOf('>', i);
  if (s < 0) return null;
  var e = raw.indexOf('</script>', s);
  if (e < 0) return null;
  try {
    var data = JSON.parse(raw.slice(s + 1, e));
    return (data && data.props && data.props.pageProps) || null;
  } catch (err) { return null; }
}
function hgBase(ctx){
  var b = (ctx && ctx.baseUrl) || '';
  return b.charAt(b.length - 1) === '/' ? b.slice(0, -1) : b;
}
function parseEpisodes(raw, context){
  var props = hgProps(raw);
  if (!props) return [];
  var base = hgBase(context);
  var book = props.bookInfoVo || {};
  var bookId = book.bookId || (context && context.id) || '';
  var pageUrl = base + '/drama/' + bookId;
  var list = props.chapterList || [];
  var out = [];
  for (var i = 0; i < list.length; i++) {
    var c = list[i];
    if (!c.chapterId) continue;
    out.push({
      id: String(c.chapterId),
      title: c.chapterName || ('第' + (i + 1) + '集'),
      number: c.chapterIndex || (i + 1),
      url: pageUrl + '#ep=' + encodeURIComponent(c.chapterId)
    });
  }
  return out;
}

video.script:
// 分集 url 形如「/drama/{bookId}#ep={chapterId}」：预取详情页后按集 ID 取 chapterVideoVo。
var HG_EP = '';
function hgProps(raw){
  if (typeof raw !== 'string') return null;
  var i = raw.indexOf('__NEXT_DATA__');
  if (i < 0) return null;
  var s = raw.indexOf('>', i);
  if (s < 0) return null;
  var e = raw.indexOf('</script>', s);
  if (e < 0) return null;
  try {
    var data = JSON.parse(raw.slice(s + 1, e));
    return (data && data.props && data.props.pageProps) || null;
  } catch (err) { return null; }
}
function hgPick(props, epId){
  var list = (props && props.chapterList) || [];
  for (var i = 0; i < list.length; i++) {
    if (String(list[i].chapterId) !== String(epId)) continue;
    var v = list[i].chapterVideoVo || {};
    return v.m3u8 || v.m3u8720p || v.vodMp4Url || v.mp4 || '';
  }
  return '';
}
function parseVideo(raw, context){
  var url = (context && context.url) || '';
  var cut = url.indexOf('#ep=');
  HG_EP = cut >= 0 ? decodeURIComponent(url.slice(cut + 4)) : '';
  var hit = hgPick(hgProps(raw), HG_EP);
  if (hit) return hit;
  var target = cut >= 0 ? url.slice(0, cut) : url;
  if (target.indexOf('http') === 0) {
    return { __meta: true, __fetchUrl: target, __fetchResponseType: 'text', __processor: 'hgPick2' };
  }
  return '';
}
function hgPick2(raw){ return hgPick(hgProps(raw), HG_EP); }
